//! Memories photos: the shared core (docs/MEMORIES-PHOTOS.md §3–§4) — a line-for-line port of
//! Tin Hat Web's `src/features/media/memories/photos.ts`. Both replay `testvectors/memories-photos/vectors.json`
//! (generated by an independent reference, `scripts/memories-photos-oracle.py`; this repo owns the file, the web keeps a
//! byte-identical copy). Pure: no Qt, no I/O.
//!
//! A Memories photo is a normal image message in the room (encrypted where the room is). The reference is the room
//! state `dev.tinhat.memories` keyed by the WRITER's own user id (Matrix rejects an "@" state key that isn't the
//! sender), content `{v: 1, photos: [{event_id, ts}], hidden: [event_id]}`: event ids and a sort time only.

use std::cmp::Ordering;
use std::collections::{HashMap, HashSet};

use serde_json::{json, Map, Number, Value};
use tinhat_theme::canon::canon_json;

/// The room state type of a person's Memories list (state_key = their own user id).
pub const MEMORIES_TYPE: &str = "dev.tinhat.memories";
/// Entries kept per list (photos, and a moderator's take-downs, each).
pub const MAX_ENTRIES: usize = 500;
/// A list's serialised size budget (UTF-8 bytes of its compact JSON), under the 64 KiB event limit.
pub const MAX_BYTES: usize = 49152;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Filter {
    All,
    Recordings,
    Photos,
}

impl Filter {
    /// "all" | "recordings" | "photos" (anything else = all).
    pub fn parse(s: &str) -> Filter {
        match s {
            "recordings" => Filter::Recordings,
            "photos" => Filter::Photos,
            _ => Filter::All,
        }
    }
}

/// One timeline item: a recording session or a photo message, at its time.
#[derive(Clone, Debug, PartialEq)]
pub struct Item {
    pub photo: bool,
    pub id: String,
    pub at: Number,
}

impl Item {
    pub fn to_json(&self) -> Value {
        json!({"kind": if self.photo { "photo" } else { "recording" }, "id": self.id, "at": Value::Number(self.at.clone())})
    }
    pub fn from_json(v: &Value) -> Option<Item> {
        Some(Item {
            photo: v.get("kind")?.as_str()? == "photo",
            id: v.get("id")?.as_str()?.to_string(),
            at: v.get("at")?.as_number()?.clone(),
        })
    }
}

fn num(v: Option<&Value>) -> Option<&Number> {
    v.and_then(Value::as_number).filter(|n| n.as_f64().is_some_and(f64::is_finite))
}

fn f(n: &Number) -> f64 {
    n.as_f64().unwrap_or(0.0)
}

/// Newer first (descending), equal = Equal.
fn newest_first(a: &Number, b: &Number) -> Ordering {
    f(b).partial_cmp(&f(a)).unwrap_or(Ordering::Equal)
}

/// The Memories timeline: recordings (their `start_ms`) and photos (their message's time), newest first, the filter
/// applied. Ties: recordings before photos, then id ascending (code-point order). Items without an id or a finite
/// time are left out.
pub fn timeline(recordings: &[Value], photos: &[Value], filter: Filter) -> Vec<Item> {
    let mut out = Vec::new();
    if filter != Filter::Photos {
        for r in recordings {
            if let (Some(id), Some(at)) = (r.get("id").and_then(Value::as_str).filter(|s| !s.is_empty()), num(r.get("start_ms"))) {
                out.push(Item { photo: false, id: id.to_string(), at: at.clone() });
            }
        }
    }
    if filter != Filter::Recordings {
        for p in photos {
            if let (Some(id), Some(at)) = (p.get("event_id").and_then(Value::as_str).filter(|s| !s.is_empty()), num(p.get("ts"))) {
                out.push(Item { photo: true, id: id.to_string(), at: at.clone() });
            }
        }
    }
    out.sort_by(|a, b| newest_first(&a.at, &b.at).then(a.photo.cmp(&b.photo)).then(a.id.cmp(&b.id)));
    out
}

/// The photo the viewer's Previous (-1) / Next (+1) goes to from `current` in `items` (photos only, no wrap), or "".
pub fn step(items: &[Item], current: &str, dir: i32) -> String {
    let photos: Vec<&Item> = items.iter().filter(|i| i.photo).collect();
    let Some(at) = photos.iter().position(|i| i.id == current) else { return String::new() };
    let next = at as i64 + dir as i64;
    if next < 0 {
        return String::new();
    }
    photos.get(next as usize).map(|i| i.id.clone()).unwrap_or_default()
}

/// The window's subtitle count: "3 recordings · 12 photos" (a zero part is left out; nothing → "").
pub fn count_text(recordings: u64, photos: u64) -> String {
    let mut parts = Vec::new();
    if recordings > 0 {
        parts.push(format!("{recordings} {}", if recordings == 1 { "recording" } else { "recordings" }));
    }
    if photos > 0 {
        parts.push(format!("{photos} {}", if photos == 1 { "photo" } else { "photos" }));
    }
    parts.join(" · ")
}

/// A photo's comment count: the server's thread aggregation on its message (`unsigned["m.relations"]["m.thread"]
/// .count`: relations only, the comments stay encrypted). Approximate by nature (docs/MEMORIES-PHOTOS.md). `unsigned` = the
/// event's `unsigned` object.
pub fn comment_count(unsigned: &Value) -> u64 {
    match unsigned.get("m.relations").and_then(|r| r.get("m.thread")).and_then(|t| t.get("count")).and_then(Value::as_f64) {
        Some(n) if n.is_finite() && n > 0.0 => n.floor() as u64,
        _ => 0,
    }
}

// ---- the window on a server with / without a call recorder ------------------------------------------------------

const REC_EMPTY: &str = "Press ⏺ Rec in a call and every stream and voice is saved for reliving later — with 🔖 Clip to bookmark the good bits. Add photos and screenshots with Add photos.";
const PHOTO_EMPTY: &str = "Add photos or screenshots with Add photos, or choose Add to Memories on one of your images in the chat.";

/// What the Memories window is on this server (the web's windowMode). Memories opens on every server; one without a
/// call recorder (memories:false in its announcement) shows photos only: no recordings fetched, no Recordings filter,
/// no recording words. `recorder` = the server records calls. As JSON (snake_case keys, the vectors' shape).
pub fn window_mode(recorder: bool) -> Value {
    let mut v = if recorder {
        json!({ "recordings": true, "filters": ["all", "recordings", "photos"], "subtitle_empty": "recordings and photos of this room",
                "empty_title": "No memories here yet", "empty_text": REC_EMPTY, "tip": "Memories — relive this room's recorded calls" })
    } else {
        json!({ "recordings": false, "filters": [], "subtitle_empty": "photos of this room",
                "empty_title": "No photos here yet", "empty_text": PHOTO_EMPTY, "tip": "Memories — this room's photos" })
    };
    v["photos_empty_title"] = json!("No photos here yet");
    v["photos_empty_text"] = json!(PHOTO_EMPTY);
    v
}

/// 2-5: my pending (just-written) list wins over the store only while the store still shows the very event my write
/// replaced (sync hasn't caught up); any other event there (my write itself, or another device's newer one) wins.
/// `pending` = `{event_id, replaced}` (anything else never wins).
pub fn pending_wins(store_event_id: &str, pending: &Value) -> bool {
    pending.as_object().and_then(|o| o.get("replaced")).and_then(Value::as_str).is_some_and(|r| r == store_event_id)
}

/// 2-8: where a photo's comments go: a photo posted INSIDE a thread → that thread (its root); otherwise the photo.
pub fn thread_root(event_id: &str, content: &Value) -> String {
    if let Some(rel) = content.get("m.relates_to").filter(|r| r.is_object()) {
        if rel.get("rel_type").and_then(Value::as_str) == Some("m.thread") {
            if let Some(id) = id_of(rel.get("event_id")) {
                return id.to_string();
            }
        }
    }
    event_id.to_string()
}

/// 2-8 (launch-gate ruling): a photo's Comments button (the web's commentsFace). A photo posted inside a thread takes
/// its comments to that thread and shows NO count (the thread's count is not the photo's): "Comments in thread".
/// Otherwise the photo's own thread with its count. JSON `{root, count (null = none), button}`.
pub fn comments_face(event_id: &str, content: &Value, count: &Value) -> Value {
    let root = thread_root(event_id, content);
    if root != event_id {
        return json!({ "root": root, "count": Value::Null, "button": "Comments in thread" });
    }
    let n = match count.as_f64() {
        Some(x) if x.is_finite() && x > 0.0 => x.floor() as u64,
        _ => 0,
    };
    let button = match n {
        0 => "Comment".to_string(),
        1 => "1 comment".to_string(),
        _ => format!("{n} comments"),
    };
    json!({ "root": event_id, "count": n, "button": button })
}

// ---- the lists (dev.tinhat.memories) ------------------------------------------------------------------------------

/// An event id a list may name: "$" + 1–254 printable ASCII characters (no spaces).
pub fn is_id(s: &str) -> bool {
    let b = s.as_bytes();
    b.len() >= 2 && b.len() <= 255 && b[0] == b'$' && b[1..].iter().all(|c| (0x21..=0x7e).contains(c))
}

fn id_of(v: Option<&Value>) -> Option<&str> {
    v.and_then(Value::as_str).filter(|s| is_id(s))
}

#[derive(Clone, Debug, PartialEq)]
pub struct Ref {
    pub event_id: String,
    pub ts: Number,
}

impl Ref {
    fn to_json(&self) -> Value {
        json!({"event_id": self.event_id, "ts": Value::Number(self.ts.clone())})
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct List {
    pub owner: String,
    pub photos: Vec<Ref>,
    pub hidden: Vec<String>,
}

impl List {
    pub fn to_json(&self) -> Value {
        json!({"owner": self.owner, "photos": self.photos.iter().map(Ref::to_json).collect::<Vec<_>>(), "hidden": self.hidden})
    }
}

fn refs_of(v: Option<&Value>) -> Vec<Ref> {
    let mut out: Vec<Ref> = Vec::new();
    let mut seen = HashSet::new();
    let Some(a) = v.and_then(Value::as_array) else { return out };
    for e in a {
        if out.len() >= MAX_ENTRIES {
            break;
        }
        let (Some(id), Some(ts)) = (id_of(e.as_object().and_then(|o| o.get("event_id"))), num(e.as_object().and_then(|o| o.get("ts")))) else { continue };
        if !seen.insert(id.to_string()) {
            continue;
        }
        out.push(Ref { event_id: id.to_string(), ts: ts.clone() });
    }
    out
}

fn ids_of(v: Option<&Value>) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let Some(a) = v.and_then(Value::as_array) else { return out };
    for e in a {
        if out.len() >= MAX_ENTRIES {
            break;
        }
        if let Some(id) = id_of(Some(e)) {
            if !out.iter().any(|x| x == id) {
                out.push(id.to_string());
            }
        }
    }
    out
}

fn is_one(v: Option<&Value>) -> bool {
    v.and_then(Value::as_f64) == Some(1.0)
}

/// One state event as a list (R1 + R2), or None: the key must be the sender's own user id, `v` must be 1.
pub fn parse_list(state_key: &Value, sender: &Value, content: &Value) -> Option<List> {
    let key = state_key.as_str()?;
    if !key.starts_with('@') || sender.as_str() != Some(key) {
        return None;
    }
    let o = content.as_object()?;
    if !is_one(o.get("v")) {
        return None;
    }
    Some(List { owner: key.to_string(), photos: refs_of(o.get("photos")), hidden: ids_of(o.get("hidden")) })
}

#[derive(Clone, Debug, PartialEq)]
pub struct Candidate {
    pub event_id: String,
    pub owner: String,
    pub ts: Number,
}

impl Candidate {
    pub fn to_json(&self) -> Value {
        json!({"event_id": self.event_id, "owner": self.owner, "ts": Value::Number(self.ts.clone())})
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Candidates {
    pub photos: Vec<Candidate>,
    pub hidden: Vec<String>,
}

impl Candidates {
    pub fn to_json(&self) -> Value {
        json!({"photos": self.photos.iter().map(Candidate::to_json).collect::<Vec<_>>(), "hidden": self.hidden})
    }
    pub fn from_json(v: &Value) -> Candidates {
        let photos = v
            .get("photos")
            .and_then(Value::as_array)
            .map(|a| {
                a.iter()
                    .filter_map(|p| {
                        Some(Candidate {
                            event_id: p.get("event_id")?.as_str()?.to_string(),
                            owner: p.get("owner")?.as_str()?.to_string(),
                            ts: p.get("ts")?.as_number()?.clone(),
                        })
                    })
                    .collect()
            })
            .unwrap_or_default();
        let hidden = v.get("hidden").and_then(Value::as_array).map(|a| a.iter().filter_map(|h| h.as_str().map(str::to_string)).collect()).unwrap_or_default();
        Candidates { photos, hidden }
    }
}

/// Every (photo, owner) pair the room's lists name (R4: nothing deduplicated away before the fetch) + the take-downs
/// of the people who are moderators now (`mods`, R3). Photos: newest first, then event id, then owner; hidden: sorted.
/// `states`: `{state_key, sender, content}` each.
pub fn candidates(states: &[Value], mods: &[String]) -> Candidates {
    let mut photos: Vec<Candidate> = Vec::new();
    let mut seen = HashSet::new();
    let mut hidden: Vec<String> = Vec::new();
    let null = Value::Null;
    for st in states {
        let Some(l) = parse_list(st.get("state_key").unwrap_or(&null), st.get("sender").unwrap_or(&null), st.get("content").unwrap_or(&null)) else { continue };
        for r in &l.photos {
            if !seen.insert((r.event_id.clone(), l.owner.clone())) {
                continue;
            }
            photos.push(Candidate { event_id: r.event_id.clone(), owner: l.owner.clone(), ts: r.ts.clone() });
        }
        if mods.iter().any(|m| *m == l.owner) {
            for h in l.hidden {
                if !hidden.contains(&h) {
                    hidden.push(h);
                }
            }
        }
    }
    photos.sort_by(|a, b| newest_first(&a.ts, &b.ts).then_with(|| a.event_id.cmp(&b.event_id)).then_with(|| a.owner.cmp(&b.owner)));
    hidden.sort();
    Candidates { photos, hidden }
}

/// What the app learned fetching one photo's event (decrypted).
#[derive(Clone, Debug, PartialEq)]
pub struct Fetched {
    pub sender: String,
    pub room_id: String,
    pub kind: String,
    pub msgtype: String,
    pub redacted: bool,
    pub ts: Option<Number>,
}

impl Fetched {
    /// `{sender, room_id, type, msgtype, redacted, ts}`; null (or anything that isn't an object) = None = unavailable.
    pub fn from_json(v: &Value) -> Option<Fetched> {
        let o = v.as_object()?;
        let s = |k: &str| o.get(k).and_then(Value::as_str).unwrap_or("").to_string();
        Some(Fetched {
            sender: s("sender"),
            room_id: s("room_id"),
            kind: s("type"),
            msgtype: s("msgtype"),
            redacted: o.get("redacted").and_then(Value::as_bool).unwrap_or(false),
            ts: num(o.get("ts")).cloned(),
        })
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Shown {
    pub photos: Vec<Candidate>,
    pub unavailable: u64,
}

impl Shown {
    pub fn to_json(&self) -> Value {
        json!({"photos": self.photos.iter().map(Candidate::to_json).collect::<Vec<_>>(), "unavailable": self.unavailable})
    }
}

/// The photos to show (R5): not taken down, fetched, an image message of this room that isn't redacted, and named by
/// its SENDER's own list. Newest first (the message's own time), then event id. `unavailable` = how many couldn't be
/// read here (None: history visibility, no key yet); not-yet-fetched ids (absent) are neither shown nor counted.
pub fn shown(c: &Candidates, fetched: &HashMap<String, Option<Fetched>>, room_id: &str) -> Shown {
    let mut out: Vec<Candidate> = Vec::new();
    let mut done = HashSet::new();
    let mut unavailable = 0u64;
    for p in &c.photos {
        if done.contains(&p.event_id) || c.hidden.contains(&p.event_id) {
            continue;
        }
        let Some(entry) = fetched.get(&p.event_id) else { continue };
        done.insert(p.event_id.clone());
        let Some(fe) = entry else {
            unavailable += 1;
            continue;
        };
        let Some(ts) = fe.ts.as_ref() else { continue };
        if fe.room_id != room_id || fe.kind != "m.room.message" || fe.msgtype != "m.image" || fe.redacted {
            continue;
        }
        if !c.photos.iter().any(|q| q.event_id == p.event_id && q.owner == fe.sender) {
            continue;
        }
        out.push(Candidate { event_id: p.event_id.clone(), owner: fe.sender.clone(), ts: ts.clone() });
    }
    out.sort_by(|a, b| newest_first(&a.ts, &b.ts).then_with(|| a.event_id.cmp(&b.event_id)));
    Shown { photos: out, unavailable }
}

// ---- writing my own list ------------------------------------------------------------------------------------------

/// My list's next content, or why it can't be written: "full" (500 entries / the byte budget) or "newer" (a later
/// version of the app wrote it: never overwritten).
#[derive(Clone, Debug, PartialEq)]
pub enum Edit {
    Content(Map<String, Value>),
    Error(&'static str),
}

impl Edit {
    pub fn to_json(&self) -> Value {
        match self {
            Edit::Content(m) => json!({"content": Value::Object(m.clone())}),
            Edit::Error(e) => json!({"error": e}),
        }
    }
}

fn edit(current: &Value, change: impl FnOnce(&mut Vec<Ref>, &mut Vec<String>)) -> Edit {
    let mut base: Map<String, Value> = current.as_object().cloned().unwrap_or_default();
    if base.contains_key("v") && !is_one(base.get("v")) {
        return Edit::Error("newer");
    }
    let mut photos = refs_of(base.get("photos"));
    let mut hidden = ids_of(base.get("hidden"));
    change(&mut photos, &mut hidden);
    if photos.len() > MAX_ENTRIES || hidden.len() > MAX_ENTRIES {
        return Edit::Error("full");
    }
    base.insert("v".into(), json!(1));
    base.insert("photos".into(), Value::Array(photos.iter().map(Ref::to_json).collect()));
    base.insert("hidden".into(), Value::Array(hidden.into_iter().map(Value::String).collect()));
    if canon_json(&Value::Object(base.clone())).len() > MAX_BYTES {
        return Edit::Error("full");
    }
    Edit::Content(base)
}

/// Add one of MY photo messages to my list (no-op when it's there). `r` = `{event_id, ts}`.
pub fn with_photo(current: &Value, r: &Value) -> Edit {
    edit(current, |photos, _| {
        let (Some(id), Some(ts)) = (id_of(r.get("event_id")), num(r.get("ts"))) else { return };
        if !photos.iter().any(|p| p.event_id == id) {
            photos.push(Ref { event_id: id.to_string(), ts: ts.clone() });
        }
    })
}

/// Take a photo off my list.
pub fn without_photo(current: &Value, event_id: &str) -> Edit {
    edit(current, |photos, _| photos.retain(|p| p.event_id != event_id))
}

/// A moderator's take-down (counts only while they are a moderator).
pub fn with_hidden(current: &Value, event_id: &str) -> Edit {
    edit(current, |_, hidden| {
        if is_id(event_id) && !hidden.iter().any(|h| h == event_id) {
            hidden.push(event_id.to_string());
        }
    })
}

/// Undo a take-down.
pub fn without_hidden(current: &Value, event_id: &str) -> Edit {
    edit(current, |_, hidden| hidden.retain(|h| h != event_id))
}

// ---- the chat (12.1.17): a Memories photo leaves the chat ----------------------------------------------------------

/// The content key of a photo posted by Memories' "Add photos": `{"dev.tinhat.memories": {"v": 1}}` (encrypted with the
/// message where the room is). The sender's own word that it is for Memories: makes it quiet, never hides it.
pub const POST_KEY: &str = "dev.tinhat.memories";

// The words both apps show for this (byte-identical; the shared vectors' `words`).
/// The "Add photos" button's tip.
pub const ADD_TIP: &str = "Add photos or screenshots to this room's Memories. They stay out of the chat (older apps still show them there).";
/// The toast after "Add to Memories" / "Add photos".
pub const ADDED_TOAST: &str = "Added to Memories. It's out of the chat now.";
/// The toast after "Remove from Memories" on my own photo.
pub const REMOVED_TOAST: &str = "Removed from Memories. It's back in the chat.";
/// The remove dialog's line.
pub const REMOVE_TEXT: &str = "It goes back into the chat.";
/// What a reply to a photo the chat hides quotes.
pub const QUOTE: &str = "Photo in Memories";
/// A moderator's Delete in the photo viewer (a photo in Memories isn't in the chat: its delete lives there too).
pub const DELETE: &str = "Delete";
pub const DELETE_TITLE: &str = "Delete this photo?";
pub const DELETE_TEXT: &str = "It's deleted for everyone: from Memories and from the chat.";
pub const DELETED_TOAST: &str = "Photo deleted.";

/// A message as the chat rules see it: its id, sender, (decrypted) type, redacted flag, msgtype and the post marker.
#[derive(Clone, Copy, Debug)]
pub struct ChatMsg<'a> {
    pub event_id: &'a str,
    pub sender: &'a str,
    pub kind: &'a str,
    pub redacted: bool,
    pub msgtype: &'a str,
    pub marker: Option<&'a Value>,
    /// round 2: in a thread (an m.thread / io.element.thread relation naming an event: threads::thread_of)
    pub in_thread: bool,
}

impl<'a> ChatMsg<'a> {
    /// `{event_id, sender, type, redacted, content}` (the vectors' shape); None when any field isn't there or isn't of
    /// its kind (a missing redacted flag, content that isn't an object): such a message is never hidden.
    pub fn from_json(v: &'a Value) -> Option<ChatMsg<'a>> {
        let o = v.as_object()?;
        let content = o.get("content")?.as_object()?;
        Some(ChatMsg {
            event_id: o.get("event_id")?.as_str()?,
            sender: o.get("sender")?.as_str()?,
            kind: o.get("type")?.as_str()?,
            redacted: o.get("redacted")?.as_bool()?,
            msgtype: content.get("msgtype").and_then(Value::as_str).unwrap_or(""),
            marker: content.get(POST_KEY),
            in_thread: !crate::threads::thread_of(o.get("content")?).is_empty(),
        })
    }

    /// H2: a readable (decrypted) image message that isn't redacted, with a real event id and sender.
    fn ok(&self) -> bool {
        is_id(self.event_id) && self.kind == "m.room.message" && !self.redacted && self.sender.starts_with('@') && self.msgtype == "m.image"
    }
}

/// What the chat hides in one room: (event id, sender) of every photo its sender's own valid list names and no
/// moderator took down (R1–R4). Built once per change of the room's lists or power levels.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ChatIndex {
    pairs: HashSet<(String, String)>,
}

impl ChatIndex {
    pub fn is_empty(&self) -> bool {
        self.pairs.is_empty()
    }
}

/// H1–H4 as an index. `states` None = the room's lists aren't loaded: None, nothing is hidden (fail closed).
pub fn chat_index(states: Option<&[Value]>, mods: &[String]) -> Option<ChatIndex> {
    let c = candidates(states?, mods);
    let pairs = c.photos.into_iter().filter(|p| !c.hidden.contains(&p.event_id)).map(|p| (p.event_id, p.owner)).collect();
    Some(ChatIndex { pairs })
}

/// Is this message hidden from the chat? Only when its SENDER's own valid list names it (someone else's list never
/// hides it) and no moderator took it down. Fail closed: anything unsure → shown (false).
pub fn hidden_in_chat(index: Option<&ChatIndex>, m: Option<&ChatMsg>) -> bool {
    let (Some(index), Some(m)) = (index, m) else { return false };
    m.ok() && index.pairs.contains(&(m.event_id.to_string(), m.sender.to_string()))
}

/// The shared vectors' form: the room's lists (None = not loaded) + the moderators now + one message.
pub fn chat_hidden(states: Option<&[Value]>, mods: &[String], m: Option<&ChatMsg>) -> bool {
    hidden_in_chat(chat_index(states, mods).as_ref(), m)
}

/// M1: an image posted by Memories' "Add photos" (its own marker, v 1).
pub fn memories_post(m: Option<&ChatMsg>) -> bool {
    let Some(m) = m else { return false };
    m.ok() && m.marker.and_then(Value::as_object).is_some_and(|o| is_one(o.get("v")))
}

/// Quiet = hidden from the chat or a Memories post: no notification or sound, not unread, not the room's preview.
pub fn quiet_in_chat(index: Option<&ChatIndex>, m: Option<&ChatMsg>) -> bool {
    hidden_in_chat(index, m) || memories_post(m)
}

/// Round 2 (shared vectors `counts`, = photos.ts chatCounts): (silenced, uncounted). silenced = quiet (no notification,
/// no sound, never the preview); uncounted (off the badge) = quiet and NOT in a thread (a thread's message is read by
/// that thread's receipt: never taken off, the safe side).
pub fn chat_counts(index: Option<&ChatIndex>, m: Option<&ChatMsg>) -> (bool, bool) {
    let q = quiet_in_chat(index, m);
    (q, q && !m.is_some_and(|m| m.in_thread))
}

#[cfg(test)]
mod tests {
    use super::*;

    const VECTORS: &str = include_str!("../../../testvectors/memories-photos/vectors.json");

    fn vectors() -> Value {
        serde_json::from_str(VECTORS).expect("json")
    }

    fn cases<'a>(v: &'a Value, k: &str) -> &'a Vec<Value> {
        v[k].as_array().unwrap_or_else(|| panic!("no {k}"))
    }

    fn name(c: &Value) -> String {
        c["name"].as_str().unwrap_or("").to_string()
    }

    fn same(got: &Value, want: &Value, what: &str) {
        assert_eq!(canon_json(got), canon_json(want), "{what}");
    }

    #[test]
    fn constants_are_the_shared_constants() {
        let v = vectors();
        assert_eq!(v["constants"]["type"], json!(MEMORIES_TYPE));
        assert_eq!(v["constants"]["max_entries"], json!(MAX_ENTRIES));
        assert_eq!(v["constants"]["max_bytes"], json!(MAX_BYTES));
    }

    #[test]
    fn timeline_newest_first_filtered() {
        let v = vectors();
        assert!(cases(&v, "timeline").len() >= 5);
        for c in cases(&v, "timeline") {
            let got = timeline(c["recordings"].as_array().unwrap(), c["photos"].as_array().unwrap(), Filter::parse(c["filter"].as_str().unwrap()));
            same(&Value::Array(got.iter().map(Item::to_json).collect()), &c["expect"], &name(c));
        }
    }

    #[test]
    fn viewer_step_photos_only_no_wrap() {
        let v = vectors();
        for c in cases(&v, "step") {
            let items: Vec<Item> = c["items"].as_array().unwrap().iter().filter_map(Item::from_json).collect();
            assert_eq!(step(&items, c["current"].as_str().unwrap(), c["dir"].as_i64().unwrap() as i32), c["expect"].as_str().unwrap(), "{}", name(c));
        }
    }

    #[test]
    fn count_text_words() {
        let v = vectors();
        for c in cases(&v, "count_text") {
            assert_eq!(count_text(c["recordings"].as_u64().unwrap(), c["photos"].as_u64().unwrap()), c["expect"].as_str().unwrap());
        }
    }

    #[test]
    fn comment_count_thread_aggregation_numbers_only() {
        let v = vectors();
        assert!(cases(&v, "comment_count").len() >= 5);
        for c in cases(&v, "comment_count") {
            assert_eq!(comment_count(&c["unsigned"]), c["expect"].as_u64().unwrap(), "{}", name(c));
        }
    }

    #[test]
    fn window_mode_photos_only_without_a_recorder() {
        let v = vectors();
        assert_eq!(cases(&v, "window_mode").len(), 2);
        for c in cases(&v, "window_mode") {
            same(&window_mode(c["recorder"].as_bool().unwrap()), &c["expect"], &name(c));
        }
    }

    #[test]
    fn pending_write_wins_only_while_the_store_shows_what_it_replaced_2_5() {
        let v = vectors();
        assert!(cases(&v, "pending_wins").len() >= 6);
        for c in cases(&v, "pending_wins") {
            assert_eq!(pending_wins(c["store"].as_str().unwrap(), &c["pending"]), c["expect"].as_bool().unwrap(), "{}", name(c));
        }
    }

    #[test]
    fn photo_comments_inside_a_thread_go_to_that_thread_2_8() {
        let v = vectors();
        assert!(cases(&v, "thread_root").len() >= 5);
        for c in cases(&v, "thread_root") {
            assert_eq!(thread_root(c["event_id"].as_str().unwrap(), &c["content"]), c["expect"].as_str().unwrap(), "{}", name(c));
        }
    }

    #[test]
    fn comments_button_no_count_inside_a_thread_2_8() {
        let v = vectors();
        assert!(cases(&v, "comments_face").len() >= 5);
        for c in cases(&v, "comments_face") {
            same(&comments_face(c["event_id"].as_str().unwrap(), &c["content"], &c["count"]), &c["expect"], &name(c));
        }
    }

    #[test]
    fn parse_own_list_v1_validated_capped() {
        let v = vectors();
        assert!(cases(&v, "parse").len() >= 10);
        for c in cases(&v, "parse") {
            let got = parse_list(&c["state_key"], &c["sender"], &c["content"]).map(|l| l.to_json()).unwrap_or(Value::Null);
            same(&got, &c["expect"], &name(c));
        }
    }

    #[test]
    fn candidates_every_pair_moderators_takedowns() {
        let v = vectors();
        for c in cases(&v, "candidates") {
            let mods: Vec<String> = c["mods"].as_array().unwrap().iter().map(|m| m.as_str().unwrap().to_string()).collect();
            same(&candidates(c["states"].as_array().unwrap(), &mods).to_json(), &c["expect"], &name(c));
        }
    }

    #[test]
    fn shown_only_the_senders_own_list() {
        let v = vectors();
        assert!(cases(&v, "shown").len() >= 5);
        for c in cases(&v, "shown") {
            let cands = Candidates::from_json(&c["candidates"]);
            let fetched: HashMap<String, Option<Fetched>> = c["fetched"].as_object().unwrap().iter().map(|(k, f)| (k.clone(), Fetched::from_json(f))).collect();
            same(&shown(&cands, &fetched, c["room"].as_str().unwrap()).to_json(), &c["expect"], &name(c));
        }
    }

    #[test]
    fn editing_my_list() {
        let v = vectors();
        assert!(cases(&v, "edit").len() >= 12);
        for c in cases(&v, "edit") {
            let cur = &c["current"];
            let arg = &c["arg"];
            let got = match c["op"].as_str().unwrap() {
                "withPhoto" => with_photo(cur, arg),
                "withoutPhoto" => without_photo(cur, arg.as_str().unwrap()),
                "withHidden" => with_hidden(cur, arg.as_str().unwrap()),
                "withoutHidden" => without_hidden(cur, arg.as_str().unwrap()),
                op => panic!("op {op}"),
            };
            same(&got.to_json(), &c["expect"], &name(c));
        }
    }

    fn chat_case(c: &Value) -> (Option<Vec<Value>>, Vec<String>) {
        let states = c["states"].as_array().cloned();
        let mods = c["mods"].as_array().unwrap().iter().map(|m| m.as_str().unwrap().to_string()).collect();
        (states, mods)
    }

    #[test]
    fn chat_hides_only_what_its_own_senders_valid_list_names_fail_closed() {
        let v = vectors();
        assert!(cases(&v, "chat_hidden").len() >= 20);
        for c in cases(&v, "chat_hidden") {
            let (states, mods) = chat_case(c);
            let m = ChatMsg::from_json(&c["msg"]);
            assert_eq!(chat_hidden(states.as_deref(), &mods, m.as_ref()), c["expect"].as_bool().unwrap(), "{}", name(c));
        }
    }

    #[test]
    fn quiet_a_memories_post_or_a_hidden_photo() {
        let v = vectors();
        assert!(cases(&v, "quiet").len() >= 8);
        for c in cases(&v, "quiet") {
            let (states, mods) = chat_case(c);
            let idx = chat_index(states.as_deref(), &mods);
            let m = ChatMsg::from_json(&c["msg"]);
            let got = json!({"hidden": hidden_in_chat(idx.as_ref(), m.as_ref()), "post": memories_post(m.as_ref()), "quiet": quiet_in_chat(idx.as_ref(), m.as_ref())});
            same(&got, &c["expect"], &name(c));
        }
    }

    #[test]
    fn counts_silenced_quiet_uncounted_not_in_a_thread_round_2() {
        let v = vectors();
        assert!(cases(&v, "counts").len() >= 12);
        for c in cases(&v, "counts") {
            let (states, mods) = chat_case(c);
            let idx = chat_index(states.as_deref(), &mods);
            let m = ChatMsg::from_json(&c["msg"]);
            let (silenced, uncounted) = chat_counts(idx.as_ref(), m.as_ref());
            same(&json!({"silenced": silenced, "uncounted": uncounted}), &c["expect"], &name(c));
        }
    }

    #[test]
    fn chat_words_and_post_key_are_shared() {
        let v = vectors();
        assert_eq!(v["constants"]["post_key"], POST_KEY);
        same(
            &v["words"],
            &json!({"add_tip": ADD_TIP, "added_toast": ADDED_TOAST, "removed_toast": REMOVED_TOAST, "remove_text": REMOVE_TEXT, "quote": QUOTE,
                "delete": DELETE, "delete_title": DELETE_TITLE, "delete_text": DELETE_TEXT, "deleted_toast": DELETED_TOAST}),
            "words",
        );
    }
}
